    return (False, None)
# Domain checks
if not (c < b < a):
    # Must satisfy AB < AC < BC
    return (False, None)
if not (a < b + c and b < a + c and c < a + b):
    return (False, None)
if center_kind not in ['incenter', 'excenter_a', 'excenter_b', 'excenter_c']:
    return (False, None)
import math
s = 0.5 * (a + b + c)
area_sq = s * (s - a) * (s - b) * (s - c)
if area_sq <= 0:
    return (False, None)
area = math.sqrt(area_sq)
R = (a * b * c) / (4.0 * area)
r = area / s
r_a = area / (s - a)
r_b = area / (s - b)
r_c = area / (s - c)
# Select rho and line-offset factors
if center_kind == 'incenter':
    rho = r
    denom = R - rho
    # incircle case uses differences
    f_a = abs(b - c) / 2.0
    f_b = abs(a - c) / 2.0
    f_c = abs(a - b) / 2.0
    if denom <= 0:
        # For all Euclidean triangles, R > r, so denom should be positive
        return (False, None)
elif center_kind == 'excenter_a':
    rho = r_a
    denom = abs(R - rho)
    f_a = (b + c) / 2.0
    f_b = (a + c) / 2.0
    f_c = (a + b) / 2.0
elif center_kind == 'excenter_b':
    rho = r_b
    denom = abs(R - rho)
    f_a = (b + c) / 2.0
    f_b = (a + c) / 2.0
    f_c = (a + b) / 2.0
else:
    rho = r_c
    denom = abs(R - rho)
    f_a = (b + c) / 2.0
    f_b = (a + c) / 2.0
    f_c = (a + b) / 2.0
if denom < 1e-12:
    return (False, None)
# Core formula (derived via homothety and parallel-line geometry):
# P = (rho / (R - rho))^3 * product of d(O, JH_*) where the latter
# evaluates to the listed f_a, f_b, f_c depending on the chosen center.
# For excenters, we use absolute value of (R - rho) to keep distances positive.
scale = rho / denom
P = (scale ** 3) * f_a * f_b * f_c
# Enforce numeric reasonability
if not (math.isfinite(P) and P > 0):
    return (False, None)
# Return with sufficient precision
answer = P
return True, answer


    def generate_valid_instance(seed: int, timeout_seconds: float = 10.0):
        """Return dict with assignment/question/answer or raise RuntimeError."""
        start = time.time()
        attempts = 0
        while time.time() - start < timeout_seconds:
            attempts += 1
            rng = _RNGShim(seed + attempts)
            assignment = generator(rng)
            valid, answer = verifier(assignment)
            if valid:
                question = LANGUAGE_WRAPPER.format(**assignment)
                return {
                    "assignment": assignment,
                    "question": question,
                    "answer": answer,
                    "attempts": attempts,
                    "elapsed_seconds": time.time() - start,
                }
        raise RuntimeError("Failed to sample a valid assignment within timeout_seconds")

